#include <iostream>
#include <vector>

int main() {
    std::vector<int> numeros;
    numeros.push_back(100);
    numeros.push_back(200);
    numeros.push_back(300);
    std::cout << numeros.size() << "\n";
    std::cout << numeros[0] << "\n";
    return 0;
}
